[
 'slug' => 'documentary-filmmaking', 'title' => 'Documentary Filmmaking', 'level' => 'Intermediate', 'category' => 'Documentary', 'duration' => '4 hours',
 'summary' => 'Research, film and structure true stories ethically: access, consent, interviews, observation and archive.',
 'description' => 'Documentaries tell true stories about real people. This course covers research, building trust, interview technique, ethical practice and story structure.',
 'outcomes' => "Choose a documentary approach for your subject\nResearch a topic and gain access\nObtain informed consent and work ethically\nConduct strong interviews and shoot useful b-roll\nStructure a documentary and use archive responsibly",
 'lessons' => [
  ['Documentary approaches and research', 16, "<p>Common approaches include <strong>observational</strong> (following events as they happen), <strong>interview-driven</strong>, <strong>essay or poetic</strong> and <strong>participatory</strong> (the filmmaker is part of the story). Many films mix these.</p><ul><li>Start with a <strong>question</strong> or a person you want to understand, not a conclusion.</li><li>Research widely: read, talk to people, visit locations, look for existing films on the subject.</li><li>Decide who your film is <strong>for</strong> and why it matters now.</li></ul>"],
  ['Access, trust and ethics', 18, "<ul><li><strong>Informed consent:</strong> explain in plain language what the film is about, how the footage will be used and who may see it. Get consent in writing or on camera. People may refuse or withdraw early on.</li><li><strong>Do no harm:</strong> think about safety, dignity and privacy, especially for children, survivors of violence and people who could face danger because of what they say.</li><li><strong>Fair representation:</strong> do not stage events and present them as real, and do not edit to change what someone meant.</li><li><strong>Respect communities:</strong> spend time with them, listen and share the film back with them where you can.</li></ul>"],
  ['Interviews and b-roll', 18, "<ul><li><strong>Prepare</strong> open questions (“Tell me about…”) rather than yes/no questions.</li><li>Put the interviewee at ease; film in a quiet, familiar place with good sound.</li><li><strong>Listen</strong> and follow up; silence often brings the best answers.</li><li>Ask them to include the question in their answer so the editor can cut out your voice.</li><li>Shoot plenty of <strong>b-roll</strong>: hands, places, objects, activities that illustrate what they say. Shoot sequences (wide, medium, close) not just single shots.</li></ul>"],
  ['Structure and archive', 16, "<ul><li>Find the <strong>story</strong>: who wants what, what changes? A documentary still needs a beginning, middle and end.</li><li>Write a <strong>paper edit</strong> (an outline from transcripts) before you cut.</li><li><strong>Archive</strong> photos, video and music add context but have owners. Get written permission or use material that is in the public domain or openly licensed, and credit it.</li><li>Fact-check every claim before release.</li></ul>"],
 ],
 'questions' => [
